        let mut vf2 = V::ld(c.vf[2]);
        let mut vf3 = V::ld(c.vf[3]);
        let mut vf4 = V::ld(c.vf[4]);
        let mut vf5 = V::ld(c.vf[5]);
        let mut acc = V::ld(c.vacc);
