                    g.begin();
                    t1 = x as u64;
                    // k3 lbu $a2, 8($at) @0x674
                    let a = (at as u32).wrapping_add(8);
                    g.end();
                    let x = ld8!(c, fr, fm, a, 6, fr.pc(0x674), ic0 + 3, 33);
                    g.begin();
                    a2 = x as u64;
                    // k4 sll $t5, $t5, 6 @0x678
                    t5 = sx32((t5 as u32) << 6);
                    // k5 lw $a3, 4($at) @0x67c
                    let a = (at as u32).wrapping_add(4);
                    g.end();
                    let x = ld32!(c, fr, fm, a, 7, fr.pc(0x67c), ic0 + 5, 31);
                    g.begin();
                    a3w = (a3w & HI) | (sx32(x) as u128);
