                    t1 = sx32((t1 as u32) << 3);
                    // k9 lbu $a0, 9($at) @0x68c
                    let a = (at as u32).wrapping_add(9);
                    g.end();
                    let x = ld8!(c, fr, fm, a, 4, fr.pc(0x68c), ic0 + 9, 27);
                    g.begin();
