                    a2 = sx32((a2 as u32).wrapping_add(t2 as u32));
                    // k25 add $a1, $a1, $t2 @0x6cc
                    a1w = (a1w & HI) | (sx32((a1w as u32).wrapping_add(t2 as u32)) as u128);
