                c.icount = ic;
                c.r[3] = v1;
                c.r[4] = a0;
                c.r[5] = a1;
                c.r[6] = a2;
                c.r[7] = a3;
                c.r[8] = t0;
                c.r[9] = t1;
                c.r[13] = t5;
                c.f[0] = f0;
                c.f[1] = f1;
                c.f[2] = f2;
