                    g.begin(); // re-arm after a possible slow access (flush ended the Chop)
                    // 0x7a0 sll $t5, $t5, 6
                    t5 = put(t5, sx32((t5 as u32) << 6));
                    // 0x7a4 lbu $a2, 8($at)
                    let x = ld8!(c, fr, fm, (at as u32).wrapping_add(8), 6, fr.pc(0x7a4), ic0 + 3, 39);
                    a2 = put(a2, x as u64);
                    g.begin(); // re-arm after a possible slow access (flush ended the Chop)
