                    acc = p29.mul(vf1.prep().bcx());
                    lv = acc;
                    any1 = true;
                    stk!(7, acc);
                    // 0x7b8 lbu $a0, 9($at)
                    let x = ld8!(c, fr, fm, (at as u32).wrapping_add(9), 4, fr.pc(0x7b8), ic0 + 8, 34);
                    a0 = put(a0, x as u64);
                    g.begin(); // re-arm after a possible slow access (flush ended the Chop)
                    // 0x7bc vmadday.xyz ACC, vf30, vf1y
                    acc = acc.madd(p30, vf1.prep().bcy());
                    lv = acc;
                    stk!(7, acc);
                    // 0x7c0 pref 0, ($t5): no code
                    // 0x7c4 vmaddz.xyz vf2, vf31, vf1z
                    let r2n = acc.madd(p31, vf1.prep().bcz());
