                    f0 = crate::fpu::mul(f0, f4);
                    // 0x7e8 andi $a1, $a1, 0x3ff
                    a1 = put(a1, (a1 as u64) & 0x3ff);
                    // 0x7ec add $a1, $a1, $t2
                    a1 = put(a1, sx32((a1 as u32).wrapping_add(t2 as u32)));
                    // 0x7f0 add $a2, $a2, $t2
                    a2 = put(a2, sx32((a2 as u32).wrapping_add(t2 as u32)));
                    // 0x7f4 lwc1 $f1, 0x3400($a2)
                    f1 = match fm.r32((a2 as u32).wrapping_add(0x3400)) {
                        Some(x) => x,
                        None => {
                            flush!();
                            return deopt(c, fr, fr.pc(0x7f4), ic0 + 22);
                        }
                    };
                    // 0x7f8 pextlb $a3, $zero, $a3
                    a3 = mmi::pextlb(0, a3);
                    // 0x7fc lwc1 $f2, 0x3400($a1)
                    f2 = match fm.r32((a1 as u32).wrapping_add(0x3400)) {
                        Some(x) => x,
                        None => {
                            flush!();
                            return deopt(c, fr, fr.pc(0x7fc), ic0 + 24);
                        }
                    };
                    // 0x800 pextlh $a3, $zero, $a3
                    a3 = mmi::pextlh(0, a3);
                    // 0x804 qmfc2 $a2, vf2
                    a2 = v2.to_u128();
                    // 0x808 sll $v1, $v1, 0xa
                    v1 = put(v1, sx32((v1 as u32) << 10));
                    // 0x80c lbu $a1, 7($at)
                    let x = ld8!(c, fr, fm, (at as u32).wrapping_add(7), 5, fr.pc(0x80c), ic0 + 29, 13);
                    a1 = put(a1, x as u64);
                    // 0x810 sll $a0, $a0, 0xd
                    a0 = put(a0, sx32((a0 as u32) << 13));
                    // 0x814 pminw $a0, $a0, $s3
                    a0 = mmi::pminw(a0, s3);
                    // 0x818 qmtc2 $zero, vf0: vf0 write dropped, no code
                    // 0x81c sqc2 vf1, 0($t8) (no VU0 op follows, so the Chop need not be re-armed)
                    st128!(c, fr, fm, t8 as u32, vf1.to_u128(), fr.pc(0x81c), ic0 + 33, 9);
                    // 0x820 pextuw $a2, $zero, $a2
                    a2 = mmi::pextuw(0, a2);
                    // 0x824 mul.s $f1, $f1, $f0
                    f1 = crate::fpu::mul(f1, f0);
                    // 0x828 sub $v1, $a2, $v1
                    v1 = put(v1, sx32((a2 as u32).wrapping_sub(v1 as u32)));
                    // 0x82c mul.s $f2, $f2, $f0
                    f2 = crate::fpu::mul(f2, f0);
                    // 0x830 sub $a0, $a0, $a2
                    a0 = put(a0, sx32((a0 as u32).wrapping_sub(a2 as u32)));
